import{_ as s,C as i,o as g,c as l,aj as n,G as o,j as t,a as r}from"./chunks/framework.BwH0p-pt.js";const w=JSON.parse('{"title":"Integration","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/configuration/integration.md","filePath":"3.0/configuration/integration.md","lastUpdated":1788942616000}'),h={name:"3.0/configuration/integration.md"};function d(p,e,c,m,u,y){const a=i("ImagePopup");return g(),l("div",null,[e[2]||(e[2]=n('<h1 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h1><p>Integrations let other software — an online store, an ERP, a mobile app — read and write your product data through UnoPim&#39;s API. Each integration gets its own credentials and its own set of permissions, so every connected system has exactly the access it needs and nothing more.</p><h2 id="who-the-api-acts-as" tabindex="-1">Who the API acts as <a class="header-anchor" href="#who-the-api-acts-as" aria-label="Permalink to &quot;Who the API acts as&quot;">​</a></h2><p>In UnoPim 3.0 you no longer assign one of your admin users to an integration. When you create an integration, UnoPim automatically creates a dedicated <strong>robot user</strong> behind the scenes:</p><ul><li>The robot user has only the permissions you give the integration — nothing more.</li><li>It cannot log in to the admin panel.</li><li>It does not appear in your user list, so it never gets in the way of managing your real team.</li></ul><p>This means a connected system can never do more than you allowed it, and removing a team member never breaks an integration.</p><div class="tip custom-block"><p class="custom-block-title">Upgrading from an earlier version?</p><p>Integrations created before 3.0 were switched to this model automatically during the upgrade. They keep working with their existing credentials — nothing for you to do.</p></div><h2 id="create-an-integration" tabindex="-1">Create an integration <a class="header-anchor" href="#create-an-integration" aria-label="Permalink to &quot;Create an integration&quot;">​</a></h2><p><strong>Step 1:</strong> Go to the admin panel, click <strong>Configuration → Integrations</strong> in the sidebar, and click the <strong>Create</strong> button.</p>',9)),o(a,{src:"/assets/3.0/images/configuration/configuration.png",alt:"The Integrations page with the Create button"}),e[3]||(e[3]=n("<p><strong>Step 2:</strong> Fill in the form:</p><ol><li><p><strong>Name</strong> — a name your team will recognise, like &quot;Shopify connector&quot;.</p></li><li><p><strong>Permissions</strong> — choose <strong>All</strong> or <strong>Custom</strong>:</p></li></ol>",2)),t("ul",null,[e[1]||(e[1]=t("li",null,[t("p",null,[t("strong",null,"All"),r(" — the integration may use everything the API offers.")])],-1)),t("li",null,[e[0]||(e[0]=t("p",null,[t("strong",null,"Custom"),r(" — pick exactly which areas the integration may access. Prefer this: give each integration only what it needs.")],-1)),o(a,{src:"/assets/3.0/images/configuration/saveIntegration.png",alt:"The New Integration form with name and permissions"})])]),e[4]||(e[4]=n("<p><strong>Step 3:</strong> Save. The <strong>Credentials</strong> section appears on the edit page.</p><p><strong>Step 4:</strong> Click <strong>Generate</strong>. UnoPim creates the credentials the connected system will use: a <strong>Client ID</strong>, a <strong>Secret Key</strong>, an <strong>API Username</strong> and an <strong>API Password</strong>.</p>",2)),o(a,{src:"/assets/3.0/images/configuration/apiKey.png",alt:"Generated credentials with copy buttons"}),e[5]||(e[5]=n('<div class="warning custom-block"><p class="custom-block-title">Credentials are shown only once</p><p>The Secret Key and API Password are displayed a single time, right after you generate them. Use the <strong>Copy</strong> buttons and store them somewhere safe — for example your company&#39;s password manager. Once you leave the page, UnoPim cannot show them again.</p></div><p><strong>Step 5:</strong> The integration now appears in the Integrations list, ready to hand over to the team connecting the other system.</p><h2 id="lost-the-password" tabindex="-1">Lost the password? <a class="header-anchor" href="#lost-the-password" aria-label="Permalink to &quot;Lost the password?&quot;">​</a></h2><p>You do not need to recreate the integration. Open it and click <strong>Regenerate password</strong> — UnoPim issues a new API Password and shows it once, again with a copy button. The old password stops working, so update the connected system right away. The Secret Key can be regenerated the same way with <strong>Re-Generate Secret Key</strong>.</p><h2 id="changing-what-an-integration-may-do" tabindex="-1">Changing what an integration may do <a class="header-anchor" href="#changing-what-an-integration-may-do" aria-label="Permalink to &quot;Changing what an integration may do&quot;">​</a></h2><p>Open the integration at any time and adjust its permissions. The change takes effect immediately — the robot user behind the integration is updated with it.</p>',6))])}const f=s(h,[["render",d]]);export{w as __pageData,f as default};
